import {mkdir,writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createFetcher,validateStore} from './crawl-national-stores.mjs';
import {parseWelciaStore} from './crawl-drugstores.mjs';
import {parseSundrugDirectory} from './crawl-sundrug-directory.mjs';
import {seimsUrl,parseSeimsStore} from './crawl-seims-directory.mjs';
const out='artifacts/drugstores-yokohama-welcia-2026-09-15';
await mkdir(out,{recursive:true});
const stores=[],excluded=[],coverage={};
const yokohama=s=>/^神奈川県\s*横浜市/.test(s||'');
const save=async()=>{for(const [f,v] of Object.entries({'stores.json':stores,'report.json':{generatedAt:new Date().toISOString(),scope:'神奈川県横浜市',coverage,accepted:stores.length,excluded,databaseApplied:false}}))await writeFile(`${out}/${f}`,JSON.stringify(v,null,2))};
const accept=(source,row,parse)=>{try{const s=parse();assert(yokohama(s.address));assert(s.lat>=35.1&&s.lat<=35.7&&s.lng>=139.4&&s.lng<=139.85,'Outside Yokohama coordinate envelope');stores.push({...s,city:'横浜市'});coverage[source].accepted++}catch(e){excluded.push({source,id:row.code||row.key||row.id,name:row.name,reason:e.message});coverage[source].excluded++}};
const tasks={
welcia:async()=>{const get=await createFetcher(`${out}/welcia`);for(const category of ['01','02','13']){const source=`welcia-${category}`,c=coverage[source]={accepted:0,excluded:0,discovered:0,enumerationComplete:false};const all=[];for(let offset=0;;offset+=500){const url=`https://store.welcia.co.jp/welcia/api/proxy2/shop/list?category=${category}&ex-code=only.prior&ignore-i18n=true&datum=wgs84&add=detail_group&limit=500&offset=${offset}`;const saved=await get(url),j=JSON.parse(saved.html);assert(Array.isArray(j.items));all.push(...j.items);c.expected=j.count.total;if(all.length>=j.count.total)break;assert(j.items.length>0)}assert.equal(all.length,c.expected);assert.equal(new Set(all.map(x=>x.code)).size,all.length);c.discovered=all.length;const local=all.filter(x=>yokohama(x.address_name));c.yokohamaDiscovered=local.length;for(const row of local)accept(source,row,()=>{assert.equal(row.status,'normal');assert(!/C$/.test(row.code)&&!/調剤|閉店|休業中/.test(row.name),'Dispensing-only pharmacy excluded');return validateStore({id:`welcia-${category}-${row.code}`,name:row.name,chain_name:{'01':'ウエルシア','02':'HACドラッグ','13':'コクミン'}[category],address:row.address_name,lat:Number(row.coord?.lat),lng:Number(row.coord?.lon),phone:row.phone||'',hours:parseWelciaStore(row,new Date().toISOString()).hours,coordinateDatum:'wgs84',sourceUrl:`https://store.welcia.co.jp/welcia/?shop=${row.code}`,coordinateEvidence:'Official Welcia shop API coord with explicit datum=wgs84' ,collectedAt:new Date().toISOString()})});c.enumerationComplete=true;console.log(source,JSON.stringify(c));await save()}},
sundrug:async()=>{const source='sundrug',c=coverage[source]={accepted:0,excluded:0,enumerationComplete:false};const get=await createFetcher(`${out}/sundrug`);const d=await get('https://sundrug-online.com/tools/locations/directory');const expected=Number(d.html.match(/countries\/japan">日本\s*\((\d+)\)/)?.[1]);const url='https://sundrug-online.com/tools/locations/listings/search_v2.json',body={search:{listings_container_id:'listings',coords:[36,137],tags:[],location_result:false,open_now:false,max_results:2000,max_distance:3000,max_distance_units:'km',filter_behaviour:'all'}};const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(40000)});assert(r.ok);const raw=await r.text(),collectedAt=new Date().toISOString();await writeFile(`${out}/sundrug/search-response.json`,JSON.stringify({url,body,collectedAt,html:raw}));const data=JSON.parse(raw).locations;assert.equal(data.length,expected);c.discovered=data.length;c.expected=expected;const local=data.filter(x=>yokohama([x.region?.name,x.city?.name,x.address_line_1,x.address_line_2].filter(Boolean).join('')));c.yokohamaDiscovered=local.length;for(const row of local)accept(source,row,()=>parseSundrugDirectory(row,collectedAt));c.enumerationComplete=true;console.log(source,JSON.stringify(c))},
seims:async()=>{const source='seims',c=coverage[source]={accepted:0,excluded:0,enumerationComplete:false};const get=await createFetcher(`${out}/seims`);await get('https://store.seims.co.jp/prefecture/');const a=await get(seimsUrl('key,name,address,latitude,longitude')),b=await get(seimsUrl(''));const names=JSON.parse(a.html),data=JSON.parse(b.html);assert.equal(names.items.length,names.total);assert.equal(data.items.length,data.total);assert.equal(names.total,data.total);c.discovered=data.total;const byId=new Map(names.items.map(x=>[x.key,x]));const local=data.items.filter(x=>yokohama(byId.get(x.key)?.address));c.yokohamaDiscovered=local.length;for(const row of local)accept(source,row,()=>parseSeimsStore(byId.get(row.key),row,b.collectedAt));c.enumerationComplete=true;console.log(source,JSON.stringify(c))}
};
await Promise.all(Object.entries(tasks).map(async([source,fn])=>{try{await fn()}catch(e){coverage[source]={...coverage[source],error:e.message};console.error(source,e)}finally{await save()}}));await save();console.log(JSON.stringify({accepted:stores.length,coverage}));


